// In Program.cs — already included when you call:
builder.Services.AddTempoBlazor();

// Registers DragDropService as Scoped automatically.

@inject DragDropService DragDrop

@if (DragDrop.IsDragging && DragDrop.Source == DragSource.MultiViewList)
{
    <div class="my-drop-zone" @ondrop="HandleDrop" @ondragover:preventDefault>
        Drop here
    </div>
}

@code {
    private void HandleDrop()
    {
        var ids = DragDrop.DraggedIds ?? [];
        // process ids...
        DragDrop.EndDrag();
    }
}
